TableSelectDialog.items:
{
    path: '/SalesInvoicesItems',
    parameters: {
      $filter: 'SalesInvoice/InvoiceStatus eq \'Confirmed\' and DeliveryStatus eq \'Closed\' and Quantity gt DeliveredQuantity sub QuantityLoss',
      $expand: 'SalesInvoice,SalesContract'
    }
  }

ObjectNumber.number:
{
        path: 'Quantity',
        type: 'sap.ui.model.type.Float',
        formatOptions: {
          decimals: 3,
          decimalSeparator: ',',
          groupingEnabled: true,
          groupingSeparator: '.'
        }
      }

{
        path: 'AssessedShortage',
        type: 'sap.ui.model.type.Float',
        formatOptions: {
          decimals: 3,
          decimalSeparator: ',',
          groupingEnabled: true,
          groupingSeparator: '.'
        }
      }
